  var ctx = canvas.getContext('2d');
  var DPR = Math.min(window.devicePixelRatio || 1, 2);
  var W = 0, H = 0;
  var particles = [];
  var mouse = { x: -9999, y: -9999, active: false };
  var running = false;
  var raf = null;

  function resize(){
    var rect = canvas.parentElement.getBoundingClientRect();
    W = rect.width; H = rect.height;
    canvas.width = Math.round(W * DPR);
    canvas.height = Math.round(H * DPR);
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    var count = Math.min(70, Math.max(26, Math.round(W * H / 22000)));
    particles = [];
    for(var i = 0; i < count; i++){
      particles.push({
        x: Math.random() * W,
        y: Math.random() * H,
        vx: (Math.random() - 0.5) * 0.3,
        vy: (Math.random() - 0.5) * 0.3,
        r: 1 + Math.random() * 2.1,
        p: Math.random() * Math.PI * 2
      });
    }
  }

  function themeColors(){
    var dark = document.documentElement.getAttribute('data-theme') === 'dark';
    return dark ? '239,68,68' : '185,28,28';
  }

  function step(){
    if(!running) return;
    var col = themeColors();
    ctx.clearRect(0, 0, W, H);
    var cx = W / 2, cy = H / 2;
    var i, j, a, b, dx, dy, d2, d;

    for(i = 0; i < particles.length; i++){
      a = particles[i];
      a.vx += (cx - a.x) * 0.00045;
      a.vy += (cy - a.y) * 0.00045;
      if(mouse.active){
        dx = a.x - mouse.x; dy = a.y - mouse.y;
        d2 = dx * dx + dy * dy;
        if(d2 < 160000 && d2 > 1){
          d = Math.sqrt(d2);
          var f = (400 - d) / 400 * 0.7;
          a.vx += (dx / d) * f; a.vy += (dy / d) * f;
        }
      }
      a.vx *= 0.994; a.vy *= 0.994;
      a.x += a.vx; a.y += a.vy;
      if(a.x < a.r){ a.x = a.r; a.vx *= -0.7; }
      if(a.x > W - a.r){ a.x = W - a.r; a.vx *= -0.7; }
      if(a.y < a.r){ a.y = a.r; a.vy *= -0.7; }
      if(a.y > H - a.r){ a.y = H - a.r; a.vy *= -0.7; }
    }

    var LINK = 110;
    ctx.lineWidth = 1;
    for(i = 0; i < particles.length; i++){
      a = particles[i];
      for(j = i + 1; j < particles.length; j++){
        b = particles[j];
        dx = a.x - b.x; dy = a.y - b.y;
        d2 = dx * dx + dy * dy;
        if(d2 < LINK * LINK){
          var alpha = (1 - Math.sqrt(d2) / LINK) * 0.3;
          ctx.strokeStyle = 'rgba(' + col + ',' + alpha.toFixed(3) + ')';
          ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
        }
      }
    }

    for(i = 0; i < particles.length; i++){
      a = particles[i];
      var glow = 0.5 + 0.5 * Math.sin(a.p);
      ctx.fillStyle = 'rgba(' + col + ',' + (0.45 + 0.4 * glow).toFixed(3) + ')';
      ctx.beginPath(); ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2); ctx.fill();
    }

    raf = requestAnimationFrame(step);
  }

  var heroWrap = canvas.parentElement;
  heroWrap.addEventListener('mousemove', function(e){
    var r = heroWrap.getBoundingClientRect();
    mouse.x = e.clientX - r.left; mouse.y = e.clientY - r.top; mouse.active = true;
  });
  heroWrap.addEventListener('mouseleave', function(){ mouse.active = false; });
  heroWrap.addEventListener('touchmove', function(e){
    var t = e.touches[0];
    if(t){ var r = heroWrap.getBoundingClientRect(); mouse.x = t.clientX - r.left; mouse.y = t.clientY - r.top; mouse.active = true; }
  }, {passive:true});
  heroWrap.addEventListener('touchend', function(){ mouse.active = false; });

  window.addEventListener('resize', function(){ resize(); });
  document.addEventListener('visibilitychange', function(){
    if(document.hidden){ running = false; if(raf) cancelAnimationFrame(raf); }
    else if(!running){ running = true; resize(); step(); }
  });

  running = true;
  resize();
  step();
})();

