       "https://github.com/a-5ingh",
       "https://cv.singhamarbir.com"
     ]
   },
   {
     "@context": "https://schema.org",
     "@type": "WebSite",
     "name": "Amarbir Singh",
     "url": "https://singhamarbir.com",
     "potentialAction": {
       "@type": "SearchAction",
       "target": {
         "@type": "EntryPoint",
         "urlTemplate": "https://singhamarbir.com/?q={search_term_string}"
       },
       "query-input": "required name=search_term_string"
     }
   }]
   </script>
   <script src="https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4" defer></script>
   <link rel="preload" href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&display=swap" as="style" onload="this.onload=null;this.rel='stylesheet'">
   <noscript><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;800&display=swap" rel="stylesheet"></noscript>
   <style>
     :root{ --bg: #ffffff; --text: #0f172a; --muted: #374151; }
     [data-theme="dark"]{ --bg:#0b1220; --text:#f8fafc; --muted:#9ca3af; }

     html{ background:var(--bg); color:var(--text); scroll-behavior: smooth; transition: background 0.6s ease, color 0.6s ease; overflow-x: hidden; }
     html.theme-transitioning { animation: themeGlow 0.6s ease; }
     @keyframes themeGlow { 0%{filter:brightness(1);} 30%{filter:brightness(1.15);} 100%{filter:brightness(1);} }
     body{ font-family: 'Inter', Arial, sans-serif; margin:0; padding:20px; background:transparent; color:var(--text); min-height:100vh; display:flex; flex-direction:column; transition: color 0.5s ease; }

     /* intro animation */
     .intro-overlay { position:fixed; inset:0; background:var(--bg); z-index:9999; display:flex; align-items:center; justify-content:center; padding:1rem; opacity:1; transition: opacity 0.8s ease, visibility 0.8s ease; }
     .intro-overlay.hidden { opacity:0; visibility:hidden; pointer-events:none; }
     .intro-text { font-size:clamp(1.5rem, 5vw, 3rem); font-weight:800; opacity:0; animation: introFade 2.2s ease forwards; text-align:center; line-height:1.3; }
     @keyframes introFade { 0%{opacity:0;transform:translateY(20px);} 50%{opacity:1;transform:translateY(0);} 100%{opacity:0;transform:translateY(-10px);} }
     main.hero-wrap, #skill-area, footer { opacity:0; transition: opacity 0.8s ease; }
     main.hero-wrap.visible, #skill-area.visible, footer.visible { opacity:1; }
     main.hero-wrap { flex:1; }
     /* override specific Tailwind muted class to match theme */
     .text-gray-700 { color: var(--muted) !important; }

     /* fade-in used for tagline and chars (staggered) */
     .fade-in { opacity: 0; transform: translateY(10px) scale(.995); transition: opacity 1s cubic-bezier(.2,.9,.3,1), transform 1s cubic-bezier(.2,.9,.3,1); }
     .fade-in.visible { opacity: 1; transform: none; }

     /* creative bold cursor: diamond outline for light, filled for dark
        apply to body, links, and buttons so cursor stays consistent on hover/click */
     body, a, button, .icon-button { cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='28' height='28'><polygon points='14,3 24,14 14,25 4,14' fill='none' stroke='%23000' stroke-width='2'/></svg>") 14 14, auto; }
     [data-theme="dark"] body, [data-theme="dark"] a, [data-theme="dark"] button, [data-theme="dark"] .icon-button { cursor: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='28' height='28'><polygon points='14,3 24,14 14,25 4,14' fill='none' stroke='%23fff' stroke-width='2'/></svg>") 14 14, auto; }

     /* hero char styles */
     #hero { display:inline-block; line-height:1; }
     #hero .char { display:inline-block; will-change:transform,opacity; transition: color 0.12s ease; }
     #hero .char.space { width:.45em; }
     @media (max-width: 640px) {
       #hero .char.space { width:100%; height:0; display:block; }
     }
     /* layout tweaks */
     header { background: transparent; font-family: ui-monospace, 'Cascadia Code', 'Source Code Pro', Menlo, Consolas, monospace; }
     nav a, nav button { color: var(--muted); }
     .icon-button { border: none; background: transparent; padding: 4px; display:inline-flex; align-items:center; gap:6px; }
     .icon-button .sound-on { display: none; }
     .icon-button.on .sound-on { display: inline; }
     .icon-button.on .sound-off { display: none; }
     .theme-label { font-size: 12px; margin-left:6px; }
     /* make icons clearer and bigger */
     nav svg { width: 24px; height: 24px; }
     .theme-label { font-size: 13px; }
     .hero-wrap { position:relative; min-height: calc(100vh - 120px); display:flex; align-items:center; justify-content:center; }
     #particle-canvas { position:absolute; inset:0; width:100%; height:100%; pointer-events:none; z-index:0; }

     /* skill cloud (bottom of page) */
     #skill-area { width:100%; max-width:64rem; margin:0 auto; pointer-events:auto; padding:2rem 0 4rem; }
     #skill-cloud { display:flex; justify-content:center; gap:10px; flex-wrap:wrap; pointer-events:auto; }
     /* each skill - clean pill style */
     #skill-cloud .skill { opacity:0; font-weight:600; font-size:14px; padding:8px 16px; border-radius:20px; user-select:none; cursor:pointer; transition: opacity 0.3s ease, transform 0.3s ease, box-shadow 0.3s ease; pointer-events:none; white-space:nowrap; border:1px solid rgba(128,128,128,0.2); }
     #skill-cloud .skill::after { content:''; position:absolute; inset:-6px; border-radius:24px; pointer-events:none; }
