     function updateThemeButton(label){ var btn = document.getElementById('theme-toggle'); if(btn) { btn.title = 'Theme: ' + label; var svg = btn.querySelector('.theme-icon'); if(svg && THEME_ICONS[label]) svg.innerHTML = THEME_ICONS[label]; } }

     // helper to get effective theme for colors
     function getEffectiveTheme(){
       var t = localStorage.getItem(THEME_KEY) || 'system';
       if(t === 'system'){
