// --- PARTICLE FIELD: wave particles orbiting in elliptical rings behind hero ---
(function(){
  var canvas = document.getElementById('particle-canvas');
  if(!canvas) return;
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(reduceMotion){ canvas.style.display = 'none'; return; }

  var ctx = canvas.getContext('2d');
  var DPR = Math.min(window.devicePixelRatio || 1, 2);
  var W = 0, H = 0;
  var rings = [];
  var particles = [];
  var mouse = { x: -9999, y: -9999, active: false };
  var running = false;
  var raf = null;

  function bgColor(){
    var dark = document.documentElement.getAttribute('data-theme') === 'dark';
    return dark ? '11,18,32' : '255,255,255';
  }
  function dotColor(){
    var dark = document.documentElement.getAttribute('data-theme') === 'dark';
    return dark ? '239,68,68' : '185,28,28';
  }

  function resize(){
    var rect = canvas.parentElement.getBoundingClientRect();
    W = rect.width; H = rect.height;
    canvas.width = Math.round(W * DPR);
    canvas.height = Math.round(H * DPR);
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

    var cx = W / 2, cy = H / 2;
    var maxRx = Math.min(W, H) * 0.36;
    var ringCount = Math.max(2, Math.round(Math.min(W, H) / 300));
    rings = [];
    for(var i = 0; i < ringCount; i++){
      var t = (i + 1) / ringCount;
      var rx = maxRx * t * (0.9 + Math.random() * 0.2);
      rings.push({
        rx: rx,
        ry: rx * (0.62 + Math.random() * 0.36),
        tilt: (Math.random() - 0.5) * 0.6,
        dir: Math.random() < 0.5 ? 1 : -1,
        base: 0.011 * (1 - t) + 0.0035
      });
    }

    var count = Math.min(90, Math.max(34, Math.round(W * H / 14000)));
    particles = [];
    for(var p = 0; p < count; p++){
      var ring = rings[p % rings.length];
      particles.push({
        ring: ring,
        ang: Math.random() * Math.PI * 2,
        om: ring.dir * ring.base * (0.75 + Math.random() * 0.5),
        phase: Math.random() * Math.PI * 2,
        wobF: 3 + Math.random() * 4,
        r: 0.8 + Math.random() * 1.6,
        px: 0, py: 0
      });
    }
  }

  function step(){
    if(!running) return;
    var bg = bgColor();
    var dot = dotColor();
    ctx.fillStyle = 'rgba(' + bg + ',0.22)';
    ctx.fillRect(0, 0, W, H);

    var cx = W / 2, cy = H / 2;
    for(var i = 0; i < particles.length; i++){
      var p = particles[i];
      var g = p.ring;
      p.ang += p.om;

      var wob = Math.sin(p.ang * p.wobF + p.phase) * g.rx * 0.06;
      var rad = g.rx + wob;
      var x = cx + Math.cos(p.ang) * rad;
      var y = cy + Math.sin(p.ang) * g.ry * (rad / g.rx);

      var t = g.tilt;
      var tx = x - cx, ty = y - cy;
      x = cx + tx * Math.cos(t) - ty * Math.sin(t);
      y = cy + tx * Math.sin(t) + ty * Math.cos(t);

      if(mouse.active){
        var dx = x - mouse.x, dy = y - mouse.y;
        var d2 = dx * dx + dy * dy;
        if(d2 < 160000 && d2 > 1){
          var d = Math.sqrt(d2);
          var f = (400 - d) / 400 * 1.2;
          p.px += (dx / d) * f; p.py += (dy / d) * f;
        }
      }
      p.px *= 0.9; p.py *= 0.9;
      x += p.px; y += p.py;

      var glow = 0.5 + 0.5 * Math.sin(p.ang * 3 + p.phase);
      ctx.fillStyle = 'rgba(' + dot + ',' + (0.55 + 0.35 * glow).toFixed(3) + ')';
      ctx.beginPath(); ctx.arc(x, y, p.r, 0, Math.PI * 2); ctx.fill();
    }

    raf = requestAnimationFrame(step);
  }

  var heroWrap = canvas.parentElement;
  heroWrap.addEventListener('mousemove', function(e){
    var r = heroWrap.getBoundingClientRect();
    mouse.x = e.clientX - r.left; mouse.y = e.clientY - r.top; mouse.active = true;
  });
  heroWrap.addEventListener('mouseleave', function(){ mouse.active = false; });
  heroWrap.addEventListener('touchmove', function(e){
    var t = e.touches[0];
    if(t){ var r = heroWrap.getBoundingClientRect(); mouse.x = t.clientX - r.left; mouse.y = t.clientY - r.top; mouse.active = true; }
  }, {passive:true});
  heroWrap.addEventListener('touchend', function(){ mouse.active = false; });

  window.addEventListener('resize', function(){ resize(); });
  document.addEventListener('visibilitychange', function(){
    if(document.hidden){ running = false; if(raf) cancelAnimationFrame(raf); }
    else if(!running){ running = true; resize(); step(); }
  });

  running = true;
  resize();
  step();
})();

