// --- PARTICLE FIELD: elliptical waveform around the name ---
(function(){
  var canvas = document.getElementById('particle-canvas');
  if(!canvas) return;
  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  if(reduceMotion){ canvas.style.display = 'none'; return; }

  var ctx = canvas.getContext('2d');
  var DPR = Math.min(window.devicePixelRatio || 1, 2);
  var W = 0, H = 0, CX = 0, CY = 0, RX = 0, RY = 0, THICK = 0;
  var K = 5, A = 0.06, OMEGA = 0.6;
  var particles = [];
  var mouse = { x: -9999, y: -9999, active: false };
  var running = false;
  var raf = null;
  var time = 0, last = 0;

  function bgColor(){
    var dark = document.documentElement.getAttribute('data-theme') === 'dark';
    return dark ? '11,18,32' : '255,255,255';
  }
  function dotColor(){
    var dark = document.documentElement.getAttribute('data-theme') === 'dark';
    return dark ? '239,68,68' : '185,28,28';
  }

  // offset across band thickness: denser mid-band, lighter at edges
  function sampleOff(){
    for(var tries = 0; tries < 60; tries++){
      var u = (Math.random() * 2 - 1);
      if(Math.random() < Math.cos(u * Math.PI / 2)) return u;
    }
    return 0;
  }

  function resize(){
    var rect = canvas.parentElement.getBoundingClientRect();
    W = rect.width; H = rect.height;
    canvas.width = Math.round(W * DPR);
    canvas.height = Math.round(H * DPR);
    canvas.style.width = W + 'px';
    canvas.style.height = H + 'px';
    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

    CX = W / 2; CY = H / 2;
    RX = W * 0.42;
    RY = Math.max(H * 0.3, RX * 0.55);
    THICK = RX * 0.11;

    var count = Math.min(130, Math.max(70, Math.round(W * H / 12000)));
    particles = [];
    for(var i = 0; i < count; i++){
      particles.push({
        th: Math.random() * Math.PI * 2,
        tv: (Math.random() - 0.5) * 0.0008,
        off: sampleOff(),
        phase: Math.random() * Math.PI * 2,
        r: 0.8 + Math.random() * 1.6,
        px: 0, py: 0
      });
    }
  }

  function step(now){
    if(!running) return;
    if(!last) last = now;
    var dt = (now - last) / 1000; last = now;
    if(dt > 0.05) dt = 0.05;
    time += dt;

    var bg = bgColor();
    var dot = dotColor();
    ctx.fillStyle = 'rgba(' + bg + ',0.2)';
    ctx.fillRect(0, 0, W, H);

    for(var i = 0; i < particles.length; i++){
      var p = particles[i];
      p.th += p.tv;
      var th = p.th;

      var rE = RX * RY / Math.sqrt(Math.pow(RY * Math.cos(th), 2) + Math.pow(RX * Math.sin(th), 2));
      var wave = 1 + A * Math.sin(K * th + OMEGA * time) + A * 0.5 * Math.sin(K * 1.7 * th - OMEGA * 0.7 * time);
      var r = rE * wave + p.off * THICK + Math.sin(time * 2 + p.phase) * THICK * 0.25;
      var x = CX + Math.cos(th) * r;
      var y = CY + Math.sin(th) * r;

      if(mouse.active){
        var dx = x - mouse.x, dy = y - mouse.y;
        var d2 = dx * dx + dy * dy;
        if(d2 < 160000 && d2 > 1){
          var d = Math.sqrt(d2);
          var f = (400 - d) / 400 * 1.4;
          p.px += (dx / d) * f; p.py += (dy / d) * f;
        }
      }
      p.px *= 0.9; p.py *= 0.9;
      x += p.px; y += p.py;

