       }, 1500);
     }
     // --- THEME: system / light / dark ---
     var THEME_KEY = 'site-theme'; // values: 'system'|'light'|'dark'
     function applyTheme(t){
       var root = document.documentElement;
       // Add rolling transition effect
       root.classList.add('theme-transitioning');
       setTimeout(function(){ root.classList.remove('theme-transitioning'); }, 600);

       if(t === 'system' || !t){
         // follow prefers-color-scheme
         var sysDark = window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches;
         if(sysDark) root.setAttribute('data-theme','dark'); else root.removeAttribute('data-theme');
         localStorage.setItem(THEME_KEY,'system');
         updateThemeButton('System');
       } else if(t === 'dark'){
         root.setAttribute('data-theme','dark'); localStorage.setItem(THEME_KEY,'dark'); updateThemeButton('Dark');
       } else {
         root.removeAttribute('data-theme'); localStorage.setItem(THEME_KEY,'light'); updateThemeButton('Light');
       }
     }
     function cycleTheme(){
       var cur = localStorage.getItem(THEME_KEY) || 'system';
       var order = ['system','light','dark'];
       var next = order[(order.indexOf(cur) + 1) % order.length];
       applyTheme(next);
     }
     // Theme icons
     var THEME_ICONS = {
       'System': '<rect x="2" y="3" width="20" height="14" rx="2" ry="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/>',
       'Light': '<circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.2 4.2l1.4 1.4M18.4 18.4l1.4 1.4M1 12h2M21 12h2M4.2 19.8l1.4-1.4M18.4 5.6l1.4-1.4"/>',
       'Dark': '<path d="M21 12.79A9 9 0 1111.21 3 7 7 0 0021 12.79z"/>'
     };
     function updateThemeButton(label){ var btn = document.getElementById('theme-toggle'); if(btn) { btn.title = 'Theme: ' + label; var svg = btn.querySelector('.theme-icon'); if(svg && THEME_ICONS[label]) svg.innerHTML = THEME_ICONS[label]; } }

     // helper to get effective theme for colors
     function getEffectiveTheme(){
       var t = localStorage.getItem(THEME_KEY) || 'system';
       if(t === 'system'){
         return (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) ? 'dark' : 'light';
       }
       return t;
     }
     function monoShade(theme){
       // returns a monochrome shade suitable for theme: lighter shades on dark bg, darker on light bg
       if(theme === 'dark'){
         var a = 0.86 + Math.random()*0.12; return 'rgba(255,255,255,' + a.toFixed(2) + ')';
       } else {
         var a2 = 0.86 + Math.random()*0.12; return 'rgba(0,0,0,' + a2.toFixed(2) + ')';
       }
     }

     // initialize theme on load
     document.addEventListener('DOMContentLoaded', function(){
       var saved = localStorage.getItem(THEME_KEY) || 'system';
       applyTheme(saved);
       var tbtn = document.getElementById('theme-toggle'); if(tbtn) tbtn.addEventListener('click', cycleTheme);
     });

     // --- AUDIO: simple reliable pop sound ---
     function enableAudio(){
       try{
         if(!window.__audioCtx || window.__audioCtx.state === 'closed'){
           window.__audioCtx = new (window.AudioContext || window.webkitAudioContext)();
         }
         if(window.__audioCtx.state === 'suspended') window.__audioCtx.resume().catch(function(){});
         window.__audioEnabled = true;
         var btn = document.getElementById('sound-toggle'); if(btn){ btn.setAttribute('aria-pressed','true'); btn.classList.add('on'); }
         return true;
       }catch(e){ return false; }
     }
     function disableAudio(){
       try{ if(window.__audioCtx && typeof window.__audioCtx.close === 'function') window.__audioCtx.close(); }catch(e){}
       window.__audioCtx = null; window.__audioEnabled = false; var btn = document.getElementById('sound-toggle'); if(btn){ btn.setAttribute('aria-pressed','false'); btn.classList.remove('on'); }
     }
     document.addEventListener('pointerdown', function(){ if(!window.__audioEnabled) enableAudio(); }, { once:true, passive:true });
     document.addEventListener('DOMContentLoaded', function(){ var sbtn = document.getElementById('sound-toggle'); if(sbtn) sbtn.addEventListener('click', function(){ if(window.__audioEnabled) disableAudio(); else { var ok = enableAudio(); if(ok) playPop(700,0.06,0.06); } }); });

     // simple short pop (reliable)
     function playPop(freq, dur, volume){
       try{
         if(!window.__audioCtx || !window.__audioEnabled) return;
         var ctx = window.__audioCtx; if(ctx.state === 'suspended') ctx.resume().catch(function(){});
         var now = ctx.currentTime;
         var o = ctx.createOscillator(); var g = ctx.createGain();
         o.type = 'sine'; o.frequency.setValueAtTime(freq || 800, now);
         g.gain.setValueAtTime(volume || 0.06, now);
         g.gain.exponentialRampToValueAtTime(0.001, now + (dur || 0.06));
         o.connect(g); g.connect(ctx.destination);
         o.start(now); o.stop(now + (dur || 0.06));
       }catch(e){ }
     }

     function playChime(){ try{ playPop(720,0.06,0.06); }catch(e){} }

     // --- HERO split into chars + interactions ---
     function splitToChars(el){ var text = el.textContent||''; text = text.replace(/\s+$/,''); el.textContent=''; for(var i=0;i<text.length;i++){ var ch=text[i]; var s=document.createElement('span'); var parity = (i % 2 === 0) ? 'even' : 'odd'; s.className = 'char ' + parity + (ch=== ' ' ? ' space' : ''); s.textContent = ch; s.classList.add('fade-in'); el.appendChild(s); } }

     document.addEventListener('DOMContentLoaded', function(){
       var hero = document.getElementById('hero'); if(!hero) return;
       splitToChars(hero);
       var chars = Array.prototype.slice.call(hero.querySelectorAll('.char'));

       // Initial fade-in (no transform transition — physics handles that)
       chars.forEach(function(c,i){
         var d=(i*0.03+Math.random()*0.04).toFixed(3)+'s';
         c.style.transition='opacity 0.6s ease '+d+', color 0.12s ease';
       });
       requestAnimationFrame(function(){ document.querySelectorAll('.fade-in').forEach(function(el){ el.classList.add('visible'); }); });

       // Physics state per character
       var state = chars.map(function(){ return {x:0, y:0, vx:0, vy:0}; });
       var phys = {
         spring: 0.055, damping: 0.85,
         repelRadius: 150, repelForce: 14,
         cx: -9999, cy: -9999, active: false
       };

       // Cursor tracking
       hero.addEventListener('mousemove', function(e){
         phys.cx = e.clientX; phys.cy = e.clientY; phys.active = true;
       });
       hero.addEventListener('mouseleave', function(){ phys.active = false; });
       hero.addEventListener('touchmove', function(e){
         var t = e.touches[0]; if(t){ phys.cx = t.clientX; phys.cy = t.clientY; phys.active = true; }
       }, {passive:true});
       hero.addEventListener('touchend', function(){ phys.active = false; });

       // Char offsets from hero center (stable in document flow)
       var offsets = [];
       function calcOffsets(){
         var hr = hero.getBoundingClientRect();
         var hx = hr.left + hr.width/2, hy = hr.top + hr.height/2;
         offsets = chars.map(function(c){
           if(c.classList.contains('space')) return null;
           var r = c.getBoundingClientRect();
           return {dx: r.left + r.width/2 - hx, dy: r.top + r.height/2 - hy};
         });
       }
       calcOffsets();
       window.addEventListener('resize', calcOffsets);

       // Physics tick
       function tick(){
         var hr = hero.getBoundingClientRect();
         var hx = hr.left + hr.width/2, hy = hr.top + hr.height/2;

         for(var i=0;i<chars.length;i++){
           var s = state[i];
           var off = offsets[i];
           if(!off) continue;

           // Spring toward rest
           s.vx += -phys.spring * s.x;
           s.vy += -phys.spring * s.y;
           s.vx *= phys.damping;
           s.vy *= phys.damping;

           // Magnetic repulsion
           if(phys.active){
             var lx = hx + off.dx + s.x, ly = hy + off.dy + s.y;
             var dx = phys.cx - lx, dy = phys.cy - ly;
             var dist = Math.sqrt(dx*dx + dy*dy);
             if(dist < phys.repelRadius && dist > 1){
               var str = (phys.repelRadius - dist) / phys.repelRadius;
               var f = phys.repelForce * str * str;
               s.vx += -(dx/dist) * f;
               s.vy += -(dy/dist) * f;
             }
           }

           s.x += s.vx;
           s.y += s.vy;

           var rot = Math.max(-18, Math.min(18, s.vx * 3));
           chars[i].style.transform = 'translate3d(' + s.x.toFixed(1) + 'px,' + s.y.toFixed(1) + 'px,0) rotate(' + rot.toFixed(1) + 'deg)';
         }

         requestAnimationFrame(tick);
       }

       setTimeout(function(){ calcOffsets(); tick(); }, 120);
     });

     // --- PARTICLE FIELD: elliptical dust cloud hugging the name, hollow center ---
     (function(){
       var canvas = document.getElementById('particle-canvas');
       if(!canvas) return;
       var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
       if(reduceMotion){ canvas.style.display = 'none'; return; }

       var ctx = canvas.getContext('2d');
       var DPR = Math.min(window.devicePixelRatio || 1, 2);
       var W = 0, H = 0, CX = 0, CY = 0, R_IN = 0, R_OUT = 0, ASPECT = 0.5;
       var particles = [];
       var mouse = { x: -9999, y: -9999, active: false };
       var running = false;
       var raf = null;
       var time = 0, last = 0;

       function bgColor(){
         var dark = document.documentElement.getAttribute('data-theme') === 'dark';
         return dark ? '11,18,32' : '255,255,255';
       }
       function dotColor(){
         var dark = document.documentElement.getAttribute('data-theme') === 'dark';
         return dark ? '239,68,68' : '185,28,28';
       }

-      // normalized position across band: denser mid, lighter toward hole & outer edge
+      // normalized position across band: densest toward the inner/center, fading outward
       function sampleT(){
         for(var tries = 0; tries < 60; tries++){
           var t = Math.random();
-          if(Math.random() < Math.sin(Math.PI * t)) return t;
+          if(Math.random() < Math.cos(t * Math.PI / 2)) return t;
         }
-        return 0.5;
+        return 0;
       }

       function resize(){
         var rect = canvas.parentElement.getBoundingClientRect();
         W = rect.width; H = rect.height;
         canvas.width = Math.round(W * DPR);
         canvas.height = Math.round(H * DPR);
         canvas.style.width = W + 'px';
         canvas.style.height = H + 'px';
         ctx.setTransform(DPR, 0, 0, DPR, 0, 0);

         CX = W / 2; CY = H / 2;
         R_IN = W * 0.31;
         R_OUT = W * 0.40;

         var count = Math.min(120, Math.max(60, Math.round(W * H / 11000)));
         particles = [];
         for(var i = 0; i < count; i++){
           var t = sampleT();
           var r0 = R_IN + (R_OUT - R_IN) * t;
           var th = Math.random() * Math.PI * 2;
           var hx = CX + Math.cos(th) * r0;
           var hy = CY + Math.sin(th) * r0 * ASPECT;
           particles.push({
             hx: hx, hy: hy, t: t, th: th,
             x: hx, y: hy,
             vx: (Math.random() - 0.5) * 0.12,
             vy: (Math.random() - 0.5) * 0.12,
             phase: Math.random() * Math.PI * 2,
             r: 0.8 + Math.random() * 1.6
           });
         }
       }

       function step(now){
         if(!running) return;
         if(!last) last = now;
         var dt = (now - last) / 1000; last = now;
         if(dt > 0.05) dt = 0.05;
         time += dt;
         var breath = 1 + 0.02 * Math.sin(time * 0.4);

         var bg = bgColor();
         var dot = dotColor();
         ctx.fillStyle = 'rgba(' + bg + ',0.2)';
         ctx.fillRect(0, 0, W, H);

         for(var i = 0; i < particles.length; i++){
           var p = particles[i];
           var r0 = (R_IN + (R_OUT - R_IN) * p.t) * breath;
           var hx = CX + Math.cos(p.th) * r0;
           var hy = CY + Math.sin(p.th) * r0 * ASPECT;

           p.vx += (hx - p.x) * 0.0009 + (Math.random() - 0.5) * 0.01;
           p.vy += (hy - p.y) * 0.0009 + (Math.random() - 0.5) * 0.01;
           p.vx *= 0.96; p.vy *= 0.96;

           if(mouse.active){
             var dx = p.x - mouse.x, dy = p.y - mouse.y;
             var d2 = dx * dx + dy * dy;
             if(d2 < 160000 && d2 > 1){
               var d = Math.sqrt(d2);
               var f = (400 - d) / 400 * 0.8;
               p.vx += (dx / d) * f; p.vy += (dy / d) * f;
             }
           }

           p.x += p.vx; p.y += p.vy;

           var tw = 0.5 + 0.5 * Math.sin(p.phase + time * 1.5);
           ctx.fillStyle = 'rgba(' + dot + ',' + (0.5 + 0.4 * tw).toFixed(3) + ')';
           ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2); ctx.fill();
         }

         raf = requestAnimationFrame(step);
       }

       var heroWrap = canvas.parentElement;
       heroWrap.addEventListener('mousemove', function(e){
         var r = heroWrap.getBoundingClientRect();
         mouse.x = e.clientX - r.left; mouse.y = e.clientY - r.top; mouse.active = true;
       });
       heroWrap.addEventListener('mouseleave', function(){ mouse.active = false; });
       heroWrap.addEventListener('touchmove', function(e){
         var t = e.touches[0];
         if(t){ var r = heroWrap.getBoundingClientRect(); mouse.x = t.clientX - r.left; mouse.y = t.clientY - r.top; mouse.active = true; }
       }, {passive:true});
       heroWrap.addEventListener('touchend', function(){ mouse.active = false; });

       window.addEventListener('resize', function(){ resize(); });
       document.addEventListener('visibilitychange', function(){
         if(document.hidden){ running = false; if(raf) cancelAnimationFrame(raf); }
         else if(!running){ running = true; last = 0; resize(); raf = requestAnimationFrame(step); }
       });

       running = true;
       resize();
       raf = requestAnimationFrame(step);
     })();

     // smooth anchor scrolling
     document.querySelectorAll('a[href^="#"]').forEach(function(a){ a.addEventListener('click', function(e){ var t=document.querySelector(this.getAttribute('href')); if(t){ e.preventDefault(); t.scrollIntoView({behavior:'smooth', block:'start'}); } }); });

     // --- SKILL CLOUD: show all on hover/click ---
     (function(){
       var skills = ["Cloud","DevSecOps","AI","Infrastructure","CI/CD","Automation","SRE","Observability","AgenticAI","Kubernetes","Terraform","Monitoring"];
       var container = document.getElementById('skill-cloud'); if(!container) return;
       var hint = document.querySelector('.skill-hint');

       skills.forEach(function(s){
         var el = document.createElement('span'); el.className = 'skill'; el.setAttribute('role','img'); el.setAttribute('aria-label', s);
         el.textContent = s;
         container.appendChild(el);
       });

       // click/tap toggle for mobile
       var skillArea = document.getElementById('skill-area');
       skillArea.addEventListener('click', function(e){
         skillArea.classList.toggle('active');
       });

       // close when clicking outside
       document.addEventListener('click', function(e){
         if(!skillArea.contains(e.target)){
           skillArea.classList.remove('active');
         }
       });
     })();

     // Keyboard shortcut: T to toggle theme
     document.addEventListener('keydown', function(e){
       if(e.key === 't' || e.key === 'T'){
         if(e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
         cycleTheme();
       }
     });

     // Konami code easter egg
     (function(){
       var code = [38,38,40,40,37,39,37,39,66,65];
       var pos = 0;
       document.addEventListener('keydown', function(e){
         if(e.keyCode === code[pos]){ pos++; } else { pos = 0; }
         if(pos === code.length){
           pos = 0;
           document.documentElement.style.transition = 'transform 1.5s ease';
           document.documentElement.style.transform = 'rotate(360deg)';
           setTimeout(function(){ document.documentElement.style.transform = ''; }, 1600);
         }
       });
     })();

     // Writing section: load recent posts
     (function(){
       fetch('/blogs/index.json')
         .then(function(r){ if(!r.ok) throw new Error('no index'); return r.json(); })
         .then(function(data){
           var posts = data.posts || [];
           if(!posts.length) return;
           posts.sort(function(a,b){ return b.date.localeCompare(a.date) || b.title.localeCompare(a.title); });
           var recent = posts.slice(0, 3);
           var list = document.getElementById('writing-list');
           var section = document.getElementById('writing');
           if(!list || !section) return;
           list.innerHTML = recent.map(function(p){
             return '<div class="mb-3">' +
               '<div class="text-xs text-[var(--muted)]">' + p.date + '</div>' +
               '<a href="' + p.url + '" class="text-base font-semibold hover:underline">' + p.title + '</a>' +
               (p.excerpt ? '<p class="text-sm text-[var(--muted)] mt-0.5">' + p.excerpt + '</p>' : '') +
               '</div>';
           }).join('');
           section.classList.remove('hidden');
         });
     })();

     // Cursor coordinates
     (function(){
       var el = document.getElementById('cursor-pos');
       if(!el) return;
       document.addEventListener('mousemove', function(e){
         el.textContent = '[' + e.clientX + ', ' + e.clientY + ']';
         el.style.left = (e.clientX + 16) + 'px';
         el.style.top = (e.clientY - 10) + 'px';
       });
     })();

     // Dynamic year in footer
     var yearEl = document.getElementById('year');
     if(yearEl) yearEl.textContent = new Date().getFullYear();

     // Console welcome
     console.log('%c Hey there, developer! 👋', 'font-size:1.4rem;font-weight:bold;');
     console.log('%c Built with curiosity by Amarbir Singh.', 'font-size:0.9rem;color:#888;');
     console.log('%c https://singhamarbir.com', 'font-size:0.8rem;color:#666;');

   </script>
 </body>
